using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace Aesthetik.SchemaFix
{
    public class AesthetikSchemaFixInstallerV3 : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null)
                {
                    WriteLog("[AesthetikSchemaFixV3] No ProjectX connection string found, trying alternatives...");
                    foreach (ConnectionStringSettings s in ConfigurationManager.ConnectionStrings)
                    {
                        WriteLog("[AesthetikSchemaFixV3] Found connection: " + s.Name);
                    }
                    return;
                }
                string connStr = cs.ConnectionString;
                WriteLog("[AesthetikSchemaFixV3] Using System.Data.SqlClient with connection: " + cs.Name);

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();
                    WriteLog("[AesthetikSchemaFixV3] Connection opened successfully");
                    string[] statements = new[]
                    {
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHold') ALTER TABLE SOOrder ADD UsrComplianceHold bit NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHoldReason') ALTER TABLE SOOrder ADD UsrComplianceHoldReason nvarchar(500) NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('BAccount') AND name = 'UsrDisablePayLink') ALTER TABLE BAccount ADD UsrDisablePayLink bit NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.views WHERE name = 'UsrAuditTrailView') EXEC('CREATE VIEW UsrAuditTrailView AS SELECT CompanyID, BatchID, ChangeID, ScreenID, UserID, ChangeDate, Operation, TableName, CombinedKey, ModifiedFields FROM AuditHistory')"
                    };
                    foreach (string sql in statements)
                    {
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = sql;
                            cmd.ExecuteNonQuery();
                        }
                        string col = sql.Substring(sql.IndexOf("name = '") + 8);
                        col = col.Substring(0, col.IndexOf("'"));
                        WriteLog("[AesthetikSchemaFixV3] OK: " + col);
                    }
                }
                WriteLog("[AesthetikSchemaFixV3] All columns created successfully");
            }
            catch (Exception ex)
            {
                WriteLog("[AesthetikSchemaFixV3] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AesthetikSchemaFixV3] Inner: " + ex.InnerException.Message);
            }
        }
    }
}

using System;
using System.Configuration;
using System.Data.SqlClient;
using System.Net;
using System.Text;
using System.Collections.Generic;
using Customization;

namespace StudioB.Setup
{
    /// <summary>
    /// Dual-purpose plugin:
    /// 1. Cleanup: deletes broken StudioBAuditTrail GI (OData incompatible)
    /// 2. Snapshot: queries AuditHistory via SQL, POSTs last 7 days to studiob-api
    /// </summary>
    public class StudioBAuditGISetup : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            CleanupBrokenGI();
            PostAuditSnapshot();
        }

        private void CleanupBrokenGI()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) return;
                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();
                    int companyId = 0;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CompanyID FROM GIDesign WHERE CompanyID > 0", conn))
                    {
                        var r = cmd.ExecuteScalar();
                        if (r != null) companyId = (int)r;
                    }
                    if (companyId == 0) return;

                    string designId = null;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE Name = 'StudioBAuditTrail' AND CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", companyId);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value) designId = r.ToString();
                    }

                    if (designId != null)
                    {
                        foreach (var tbl in new[] { "GIResult", "GISort", "GIGroupBy", "GIWhere", "GIOn", "GIFilter", "GITable", "GIDesign" })
                        {
                            using (var cmd = new SqlCommand("DELETE FROM " + tbl + " WHERE DesignID = @did AND CompanyID = @cid", conn))
                            {
                                cmd.Parameters.AddWithValue("@did", designId);
                                cmd.Parameters.AddWithValue("@cid", companyId);
                                cmd.ExecuteNonQuery();
                            }
                        }
                        WriteLog("[AuditGISetup] Deleted broken GI");
                    }
                }
            }
            catch (Exception ex)
            {
                WriteLog("[AuditGISetup] GI cleanup error: " + ex.Message);
            }
        }

        private void PostAuditSnapshot()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) return;

                var rows = new List<string>();
                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();

                    // Get last 7 days of audit history
                    using (var cmd = new SqlCommand(@"
                        SELECT TOP 5000
                            a.BatchID, a.ChangeID, a.ScreenID, a.UserID,
                            a.ChangeDate, a.Operation, a.TableName,
                            a.CombinedKey, a.ModifiedFields,
                            u.Username
                        FROM UsrAuditTrailView a
                        LEFT JOIN Users u ON a.UserID = u.PKID
                        WHERE a.ChangeDate >= @since
                        ORDER BY a.ChangeDate DESC", conn))
                    {
                        cmd.Parameters.AddWithValue("@since", DateTime.UtcNow.AddDays(-7));
                        cmd.CommandTimeout = 30;
                        using (var reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                char q = '"';
                                var sb = new StringBuilder();
                                sb.Append('{');
                                sb.Append(q).Append("BatchID").Append(q).Append(':');
                                sb.Append(reader.IsDBNull(0) ? "null" : reader.GetInt64(0).ToString());
                                sb.Append(',').Append(q).Append("ChangeID").Append(q).Append(':');
                                sb.Append(reader.IsDBNull(1) ? "null" : reader.GetInt64(1).ToString());
                                sb.Append(',').Append(q).Append("ScreenID").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(2) ? "" : reader.GetString(2).Trim()).Append(q);
                                sb.Append(',').Append(q).Append("UserID").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(3) ? "" : reader.GetGuid(3).ToString()).Append(q);
                                sb.Append(',').Append(q).Append("ChangeDate").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(4) ? "" : reader.GetDateTime(4).ToString("o")).Append(q);
                                sb.Append(',').Append(q).Append("Operation").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(5) ? "" : reader.GetString(5).Trim()).Append(q);
                                sb.Append(',').Append(q).Append("TableName").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(6) ? "" : EscapeJson(reader.GetString(6))).Append(q);
                                sb.Append(',').Append(q).Append("CombinedKey").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(7) ? "" : EscapeJson(reader.GetString(7))).Append(q);
                                sb.Append(',').Append(q).Append("ModifiedFields").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(8) ? "" : EscapeJson(reader.GetString(8))).Append(q);
                                sb.Append(',').Append(q).Append("UserName").Append(q).Append(':').Append(q);
                                sb.Append(reader.IsDBNull(9) ? "" : EscapeJson(reader.GetString(9))).Append(q);
                                sb.Append('}');
                                rows.Add(sb.ToString());
                            }
                        }
                    }
                }

                WriteLog("[AuditGISetup] Queried " + rows.Count + " audit rows (7 days)");

                if (rows.Count == 0) return;

                // POST to studiob-api
                string apiUrl = "https://webhook-router-production-e161.up.railway.app/webhook/audit-snapshot";
                // Auth: webhook-router validates via route-level token if configured
                string apiToken = "";

                // URL is hardcoded — always attempt POST

                string json = "{" + (char)34 + "total" + (char)34 + ":" + rows.Count +
                    "," + (char)34 + "rows" + (char)34 + ":[" + string.Join(",", rows) + "]" +
                    "," + (char)34 + "source" + (char)34 + ":" + (char)34 + "publish-snapshot" + (char)34 +
                    "," + (char)34 + "timestamp" + (char)34 + ":" + (char)34 + DateTime.UtcNow.ToString("o") + (char)34 + "}";

                using (var wc = new WebClient())
                {
                    wc.Headers.Add("Content-Type", "application/json");
                    if (!string.IsNullOrEmpty(apiToken))
                        wc.Headers.Add("Authorization", "Bearer " + apiToken);
                    wc.UploadString(apiUrl, "POST", json);
                }

                WriteLog("[AuditGISetup] Posted " + rows.Count + " rows to studiob-api");
            }
            catch (Exception ex)
            {
                WriteLog("[AuditGISetup] Snapshot error: " + ex.Message);
            }
        }

        private static string EscapeJson(string s)
        {
            if (s == null) return "";
            var sb = new StringBuilder(s.Length);
            foreach (char c in s)
            {
                switch (c)
                {
                    case '"': sb.Append("\\\""); break;
                    case '\\': sb.Append("\\\\"); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default: sb.Append(c); break;
                }
            }
            return sb.ToString();
        }
    }
}

using System;
using System.Reflection;
using Customization;

namespace StudioB.Diagnostics
{
    /// <summary>
    /// One-time diagnostic plugin: enumerates all properties and nested BQL field
    /// classes on PX.SM.AuditHistory via reflection. Output appears in publish log
    /// as [information] entries. Remove after field names are discovered.
    /// </summary>
    public class AuditHistoryReflector : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            // Publish log truncates per-plugin entries. Concat everything into minimal WriteLog calls.
            try
            {
                var dacType = typeof(PX.SM.AuditHistory);

                // 1. ALL declared properties in ONE log entry
                var props = dacType.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
                var propList = new System.Collections.Generic.List<string>();
                foreach (var prop in props)
                {
                    string pxAttr = "";
                    try
                    {
                        foreach (var a in prop.GetCustomAttributes(false))
                        {
                            var n = a.GetType().Name;
                            if (n.StartsWith("PXDB") || n.StartsWith("PXString") || n.StartsWith("PXInt") || n.StartsWith("PXDate") || n.StartsWith("PXBool") || n.StartsWith("PXDecimal") || n.StartsWith("PXGuid") || n.StartsWith("PXLong"))
                                pxAttr = "[" + n + "]";
                        }
                    }
                    catch { }
                    propList.Add(prop.Name + "(" + prop.PropertyType.Name + ")" + pxAttr);
                }
                WriteLog("[AuditReflector] PROPS(" + props.Length + "): " + string.Join(" | ", propList));

                // 2. ALL nested BQL field classes in ONE log entry
                var nested = dacType.GetNestedTypes(BindingFlags.Public | BindingFlags.NonPublic);
                var nestedList = new System.Collections.Generic.List<string>();
                foreach (var nt in nested) nestedList.Add(nt.Name);
                WriteLog("[AuditReflector] NESTED(" + nested.Length + "): " + string.Join(" | ", nestedList));

                // 3. Also check the actual DB table by querying sys.columns
                var cs = System.Configuration.ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs != null)
                {
                    using (var conn = new System.Data.SqlClient.SqlConnection(cs.ConnectionString))
                    {
                        conn.Open();
                        // Try common audit table names
                        foreach (var tbl in new[] { "AuditHistory", "SMHistory", "ARAuditHistory", "AuditTrail", "SM205530" })
                        {
                            using (var cmd = conn.CreateCommand())
                            {
                                cmd.CommandText = "SELECT COUNT(*) FROM sys.tables WHERE name = @t";
                                cmd.Parameters.AddWithValue("@t", tbl);
                                var cnt = (int)cmd.ExecuteScalar();
                                if (cnt > 0)
                                {
                                    // Get all columns
                                    var colList = new System.Collections.Generic.List<string>();
                                    using (var cmd2 = conn.CreateCommand())
                                    {
                                        cmd2.CommandText = "SELECT c.name + '(' + t.name + ',' + CAST(c.max_length AS VARCHAR) + ')' FROM sys.columns c JOIN sys.types t ON c.user_type_id = t.user_type_id WHERE c.object_id = OBJECT_ID(@t) ORDER BY c.column_id";
                                        cmd2.Parameters.AddWithValue("@t", tbl);
                                        using (var reader = cmd2.ExecuteReader())
                                        {
                                            while (reader.Read()) colList.Add(reader.GetString(0));
                                        }
                                    }
                                    WriteLog("[AuditReflector] TABLE " + tbl + "(" + colList.Count + "): " + string.Join(" | ", colList));
                                }
                            }
                        }

                        // Also try: find tables with "Audit" in the name
                        var auditTables = new System.Collections.Generic.List<string>();
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = "SELECT name FROM sys.tables WHERE name LIKE '%Audit%' OR name LIKE '%audit%' ORDER BY name";
                            using (var reader = cmd.ExecuteReader())
                            {
                                while (reader.Read()) auditTables.Add(reader.GetString(0));
                            }
                        }
                        WriteLog("[AuditReflector] AUDIT_TABLES: " + string.Join(" | ", auditTables));

                        // Check AuditHistory table row count
                        try
                        {
                            using (var cmd = conn.CreateCommand())
                            {
                                cmd.CommandText = "SELECT TOP 1 * FROM AuditHistory";
                                using (var reader = cmd.ExecuteReader())
                                {
                                    var colNames = new System.Collections.Generic.List<string>();
                                    for (int i = 0; i < reader.FieldCount; i++)
                                        colNames.Add(reader.GetName(i) + "(" + reader.GetFieldType(i).Name + ")");
                                    WriteLog("[AuditReflector] AuditHistory_READER_COLS: " + string.Join(" | ", colNames));
                                }
                            }
                        }
                        catch (Exception ex2)
                        {
                            WriteLog("[AuditReflector] AuditHistory_QUERY_ERR: " + ex2.Message);
                        }
                    }
                }

                // 4. Base type
                WriteLog("[AuditReflector] BASE: " + dacType.BaseType?.FullName + " ASM: " + dacType.Assembly.GetName().Name);
            }
            catch (Exception ex)
            {
                WriteLog("[AuditReflector] FATAL: " + ex.GetType().FullName + ": " + ex.Message);
            }
        }
    }
}
